import * as D from './spark-db.js';
import {safeLink,splitExam,gradeAttempt,SAMPLE,publicAnswers,risk,validateBackup} from './spark-model.js';
import {parseClassroomRoster} from './roster.js';
let user,profile,isAdmin=false,course,courseId,unsubs=[],assessment=null,examId='',demoMode=false;
const $=id=>document.getElementById(id),app=$('app'),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),id=()=>crypto.randomUUID(),now=()=>D.serverTimestamp(),cp=()=>`sparkCourses/${courseId}`,ep=()=>`${cp()}/exams/${examId}`;
const owner=()=>isAdmin||course?.ownerUid===user?.uid;
function stop(){for(const f of unsubs)f();unsubs=[];assessment=null;}
function error(e){console.error(e);$('toast').textContent=e.code==='permission-denied'?'Acesso negado. Confira aprovação, matrícula e permissões no curso.':e.message||String(e);$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',9000);}
function on(key,fn){if($(key))$(key).onclick=async()=>{const b=$(key);b.disabled=true;try{await fn();}catch(e){error(e);}finally{if(b.isConnected)b.disabled=false;}};}
function page(title,html){stop();app.innerHTML=`<h1>${esc(title)}</h1>${html}`;}
function field(k,label,value='',type='text'){return `<label for="${k}">${label}</label><input id="${k}" type="${type}" value="${esc(value)}">`;}
const area=(k,label,value='')=>`<label for="${k}">${label}</label><textarea id="${k}" rows="7">${esc(value)}</textarea>`;
const select=(k,label,items,value)=>`<label for="${k}">${label}</label><select id="${k}">${items.map(([v,t])=>`<option value="${v}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select>`;
const val=k=>$(k).value.trim(),button=(k,text,cls='')=>`<button id="${k}" class="${cls}">${text}</button>`;
function download(name,data,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([type==='application/json'?JSON.stringify(data,null,2):data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),10000);}
function link(url,label='Abrir documento'){if(!url)return '';try{return `<a href="${esc(safeLink(url))}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`;}catch{return '<span>Link inválido</span>';}}
function table(head,rows){return `<div style="overflow:auto"><table><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function date(v){return v?.toDate? v.toDate().toLocaleString('pt-BR'):String(v||'');}
function nav(){ $('account').innerHTML=user?`<span>${esc(user.displayName)}</span> ${button('home','Início','outline')} ${button('out','Sair','outline')}`:button('login','Entrar com Google');on('login',D.login);on('home',home);on('out',D.logout);}
function landing(){page('Aprender, avaliar e acompanhar.',`<p>Conexões reúne cursos, avaliações e acompanhamento da turma.</p><div class="card"><h2>Acesso à plataforma</h2><p>Entre com sua conta Google. Professores e estudantes precisam de aprovação.</p>${button('enter','Entrar com Google')}</div><p>Conheça o sistema: entre com Google e escolha a demonstração. Usamos nome, telefone e e-mail para registrar seu interesse.</p>`);on('enter',D.login);}
D.onAuthStateChanged(D.auth,async u=>{user=u;try{nav();if(!u){profile=null;isAdmin=false;return landing();}isAdmin=!!await D.read('sparkAdmins/'+u.uid);profile=await D.read('sparkProfiles/'+u.uid);await home();if(profile?.status==='active'||isAdmin)await routeLink();}catch(e){error(e);}});
async function home(){nav();if(!profile&&!isAdmin)return register();if(isAdmin&&!profile)profile={name:user.displayName,role:'admin',status:'active'};if(profile.status!=='active'&&!isAdmin){page('Cadastro aguardando aprovação',`<p>Seu UID: <code>${esc(user.uid)}</code></p><p>A administração precisa aprovar seu acesso.</p>${button('refresh','Verificar aprovação')} ${button('demo','Conhecer demonstração')}`);on('refresh',async()=>{profile=await D.read('sparkProfiles/'+user.uid);home();});on('demo',demoSignup);return;}
let courses=isAdmin?await D.list('sparkCourses'):await D.list('sparkCourses',[['viewerUids','array-contains',user.uid]]);if(profile.role==='teacher'&&!isAdmin){const own=await D.list('sparkCourses',[['ownerUid','==',user.uid]]);courses=[...new Map([...courses,...own].map(c=>[c.id,c])).values()];}
page('Minha plataforma',`<p>${esc(profile.name)} · ${esc(profile.institution)} / ${esc(profile.campus)}</p><div class="actions">${isAdmin?button('admin','Administração'):''}${profile.role==='teacher'?button('new-course','Novo curso'):''}${button('join','Matrícula por código','outline')}${button('demo','Demonstração','outline')}${profile.role==='teacher'?button('bank','Banco de questões','outline')+button('renew','Meu plano / renovação','outline'):''}${isAdmin?button('backup','Backup e restauração','outline'):''}</div><div class="grid">${courses.map(c=>`<article class="card"><span class="pill">${c.closed?'Encerrado':'Em andamento'}</span><h2>${esc(c.title)}</h2><p>${esc(c.group)} · ${esc(c.periods?.join(', '))}</p>${button('c-'+c.id,'Abrir curso')}</article>`).join('')||'<p>Você ainda não tem cursos. Use o código de matrícula fornecido pelo professor.</p>'}</div>`);
for(const c of courses)on('c-'+c.id,()=>openCourse(c.id));on('new-course',()=>courseEditor());on('admin',adminPanel);on('join',joinCourse);on('demo',demoSignup);on('backup',backupPanel);on('bank',bankPanel);on('renew',renewPlan);}
function register(){page('Seu cadastro',`${field('name','Nome completo',user.displayName)}${field('phone','Telefone')}${field('institution','Instituição')}${field('campus','Campus')}${select('role','Perfil',[['student','Estudante'],['teacher','Professor'],['staff','Equipe de acompanhamento']],'student')}${button('register','Enviar cadastro')} ${button('demo','Conhecer demonstração','outline')}`);on('register',async()=>{for(const k of ['name','institution','campus'])if(!val(k))throw Error('Preencha '+k);await D.put('sparkProfiles/'+user.uid,{uid:user.uid,name:val('name'),phone:val('phone'),email:user.email,institution:val('institution'),campus:val('campus'),role:val('role'),status:'pending',createdAt:now()});profile=await D.read('sparkProfiles/'+user.uid);home();});on('demo',demoSignup);}
async function demoSignup(){const lead=await D.read('sparkLeads/'+user.uid);if(lead)return showDemo();page('Conheça a plataforma',`<p>Cadastre seu interesse para abrir uma demonstração com dados fictícios, sem acesso a turmas reais.</p>${field('lead-name','Nome',user.displayName)}${field('lead-phone','Telefone')}${field('lead-email','E-mail da conta Google',user.email,'email')}<label><input type="checkbox" id="consent"> Concordo com o registro destes dados para contato sobre o sistema.</label>${button('lead-send','Abrir demonstração')}`);$('lead-email').readOnly=true;on('lead-send',async()=>{if(!val('lead-name')||!val('lead-phone')||!$('consent').checked)throw Error('Informe nome, telefone e confirme o registro.');await D.put('sparkLeads/'+user.uid,{name:val('lead-name'),phone:val('lead-phone'),email:user.email,createdAt:now()});showDemo();});}
function showDemo(){page('Demonstração · dados fictícios',`<p>Ambiente ilustrativo. As ações abaixo não alteram o banco de dados.</p><div class="actions">${button('d-course','Curso')}${button('d-exam','Avaliação')}${button('d-track','Acompanhamento')}${button('d-back','Voltar','outline')}</div><div id="demo-content" class="card"></div>`);on('d-back',home);on('d-course',()=>{$('demo-content').innerHTML='<h2>Redes de computadores</h2><p>Turma INF1 · 1º, 2º e 3º trimestres</p><progress max="100" value="65"></progress><p>65% dos conteúdos concluídos</p><ul><li>Half-duplex e full-duplex</li><li>Aprendizagem da tabela MAC</li><li>ARP na rede local</li></ul>';});on('d-exam',()=>{$('demo-content').innerHTML='<h2>Questão de demonstração</h2><p>Half-duplex permite enviar e receber ao mesmo tempo?</p>'+button('d-yes','Sim')+button('d-no','Não')+'<p id="d-result"></p>';on('d-yes',()=>{$('d-result').textContent='Revise: no half-duplex há alternância.';});on('d-no',()=>{$('d-result').textContent='Correto. No full-duplex há envio e recepção simultâneos.';});});on('d-track',()=>{$('demo-content').innerHTML=table(['Estudante','1º trimestre','2º trimestre','Situação'],[['Ana fictícia','A','B','Regular'],['Bruno fictício','D','D','<strong style="color:#b42318">Acompanhamento prioritário</strong>']]);});$('d-course').click();}
async function adminPanel(){const people=await D.list('sparkProfiles'),plans=await D.list('sparkPlans'),payments=await D.list('sparkPlanPayments');page('Administração',`<h2>Aprovação de cadastros</h2><p>Selecione vários estudantes e aprove em lote. Perfis de professor e equipe são aprovados individualmente.</p>${table(['Selecionar','Nome / UID','Perfil','Instituição / campus','Status','Ação'],people.map(p=>[`<input type="checkbox" data-approve="${p.id}" ${p.role!=='student'?'disabled':''}>`,`${esc(p.name)}<br><code>${esc(p.id)}</code>`,esc(p.role),esc(p.institution)+' / '+esc(p.campus),esc(p.status),button('u-'+p.id,p.status==='active'?'Suspender':'Aprovar')]))}${button('bulk','Aprovar estudantes selecionados')}<h2>Planos e renovação</h2><p>Os comprovantes são links externos. A administração confere o pagamento e registra a validade. O limite de questões é validado nas regras. Os limites de alunos e de respostas são orientativos nesta edição.</p>${field('target','UID do professor')}${field('plan','Plano','free')}${field('until','Validade do plano pago','', 'date')}${field('proof','Link HTTPS do comprovante')}${button('assign-plan','Registrar plano e pagamento')}<h3>Solicitações de renovação</h3>${table(['Professor (UID)','Plano','Ciclo','Comprovante'],payments.map(p=>[esc(p.uid),esc(p.planId),esc(p.cycle),link(p.receiptLink)]))}<h3>Configuração de planos</h3>${area('plans','Planos em JSON',JSON.stringify(plans.length?plans.map(({id,...p})=>({id,...p})):[{id:'free',title:'Free',active:true,price:0,maxStudents:30,maxQuestions:10,maxResponses:30,features:{tracking:true,team:true,warnings:true,questionBank:true}}],null,2))}${button('save-plans','Salvar planos')}<h2>Interessados na demonstração</h2>${button('leads','Consultar cadastros')}<div id="leads-out"></div>`);for(const p of people)on('u-'+p.id,async()=>{await D.patch('sparkProfiles/'+p.id,{status:p.status==='active'?'suspended':'active'});adminPanel();});on('bulk',async()=>{await D.batch([...document.querySelectorAll('[data-approve]:checked')].map(x=>{const p=people.find(p=>p.id===x.dataset.approve);return {path:'sparkProfiles/'+p.id,data:{...p,status:'active'}};}));adminPanel();});on('assign-plan',async()=>{safeLink(val('proof'));const patch={planId:val('plan'),planReceiptLink:val('proof'),planExpiresAt:val('until')?D.Timestamp.fromDate(new Date(val('until')+'T23:59:59-03:00')):D.Timestamp.fromMillis(0)};await D.patch('sparkProfiles/'+val('target'),patch);alert('Registro atualizado.');});on('save-plans',async()=>{const a=JSON.parse(val('plans'));if(!Array.isArray(a)||a.some(p=>!p.id||! /^[\w-]+$/.test(p.id)))throw Error('Planos inválidos.');await D.batch(a.map(({id,...p})=>({path:'sparkPlans/'+id,data:p})));alert('Planos salvos.');});on('leads',async()=>{$('leads-out').innerHTML=table(['Nome','Telefone','E-mail'],(await D.list('sparkLeads')).map(x=>[esc(x.name),esc(x.phone),esc(x.email)]));});}
function courseEditor(existing){const c=existing||{};page(existing?'Configurar curso':'Novo curso',`${field('title','Nome do curso',c.title)}${field('group','Turma',c.group)}${field('subjects','Disciplinas, separadas por vírgula',c.subjects?.join(', '))}${field('periods','Períodos, separados por vírgula',c.periods?.join(', ')||'1º trimestre, 2º trimestre, 3º trimestre')}${field('start','Início',c.start,'date')}${field('end','Fim',c.end,'date')}${select('free','Acesso',[['yes','Gratuito'],['no','Pago com aprovação manual'] ],c.free===false?'no':'yes')}${field('price','Valor total do curso',c.price||0,'number')}${field('share','Percentual do responsável (registro)',c.revenuePercent||0,'number')}${field('header','Cabeçalho das advertências',c.warningHeader)}${field('footer','Rodapé das advertências',c.warningFooter)}${field('letterhead','Link HTTPS do papel timbrado (PDF/editável)',c.letterhead)}${button('save-course','Salvar curso')}`);on('save-course',async()=>{if(!val('title')||!val('group')||!val('start')||!val('end')||val('end')<val('start'))throw Error('Preencha título, turma e datas válidas.');safeLink(val('letterhead'));const cid=existing?.id||id();const data={title:val('title'),group:val('group'),subjects:val('subjects').split(',').map(s=>s.trim()).filter(Boolean),periods:val('periods').split(',').map(s=>s.trim()).filter(Boolean),start:val('start'),end:val('end'),free:val('free')==='yes',price:Number(val('price')),revenuePercent:Number(val('share')),warningHeader:val('header'),warningFooter:val('footer'),letterhead:val('letterhead'),ownerUid:c.ownerUid||user.uid,institution:c.institution||profile.institution,campus:c.campus||profile.campus,viewerUids:c.viewerUids||[user.uid],closed:false};await D.put('sparkCourses/'+cid,data);await D.put('sparkInvites/'+cid,{title:data.title,group:data.group,institution:data.institution,campus:data.campus});openCourse(cid);});}
async function openCourse(cid){courseId=cid;course=await D.read(cp());if(!course)throw Error('Curso não encontrado.');const team=owner()?null:await D.read(`${cp()}/team/${user.uid}`).catch(()=>null);const staff=owner()||!!team;page(course.title,`<p>${esc(course.institution)} / ${esc(course.campus)} · ${esc(course.group)} · ${esc(course.start)} a ${esc(course.end)}</p><p><strong>Código de matrícula:</strong> <code>${esc(cid)}</code></p><p>${link(shareUrl(cid),'Link deste curso')}</p>${course.closed?'<div class="notice">Curso encerrado. Novos lançamentos estão bloqueados.</div>':''}<div class="actions">${button('lessons','Conteúdos')}${button('exams','Avaliações e quizzes')}${staff?button('track','Acompanhamento e conselho'):''}${owner()?button('roster','Matrículas e pagamentos'):''}${owner()?button('settings','Configurar curso','outline'):''}${owner()?button('team','Equipe','outline'):''}${staff?button('report','Relatório acumulativo','outline'):''}${owner()?button('closure','Fechamento anual','outline'):''}</div>`);on('settings',()=>courseEditor(course));on('lessons',lessons);on('exams',exams);on('roster',roster);on('team',teamPanel);on('track',tracking);on('report',report);on('closure',closure);}
function joinCourse(){page('Solicitar matrícula',`${field('join-code','Código do curso')}${field('join-proof','Comprovante de pagamento: link HTTPS (se necessário)')}${button('send-request','Enviar solicitação')}`);on('send-request',async()=>{const cid=val('join-code');if(!/^[\w-]+$/.test(cid))throw Error('Código inválido.');const invite=await D.read('sparkInvites/'+cid);if(!invite)throw Error('Curso não encontrado.');safeLink(val('join-proof'));await D.put(`sparkCourses/${cid}/requests/${user.uid}`,{uid:user.uid,name:profile.name,status:'pending',receiptLink:val('join-proof'),createdAt:now()});alert('Matrícula solicitada em '+invite.title+'. O professor aprovará seu acesso.');home();});}
async function roster(){const requests=await D.list(cp()+'/requests'),students=await D.list(cp()+'/students');const candidates=await D.list('sparkProfiles',[['role','==','student'],['campus','==',course.campus],['institution','==',course.institution]]);page('Matrículas e pagamentos',`<p>Para cursos pagos, confira o comprovante antes de aprovar. Informe a validade de acesso para a seleção.</p>${field('valid-until','Acesso válido até (curso pago)',course.end,'date')}${table(['Selecionar','Nome','Comprovante','Status'],candidates.map(p=>{const m=students.find(s=>s.id===p.id),r=requests.find(s=>s.id===p.id);return [`<input type="checkbox" data-enroll="${p.id}">`,`${esc(p.name)}<br><small>${esc(p.email)}</small>`,r?link(r.receiptLink):'',m?.active?'Ativa':'Pendente'];}))}${button('approve-enroll','Aprovar matrículas selecionadas')}<h2>Importar Google Classroom</h2><p>O JSON será lido para localizar estudantes pelo e-mail. A importação não cria contas Google. Alunos precisam entrar e cadastrar-se primeiro; cadastros de estudantes pendentes do mesmo campus são aprovados ao confirmar as matrículas.</p><input id="roster-file" type="file" accept="application/json">${button('roster-preview','Localizar estudantes do JSON')}<div id="roster-preview-out"></div>`);on('approve-enroll',async()=>{const ids=[...document.querySelectorAll('[data-enroll]:checked')].map(x=>x.dataset.enroll);if(!ids.length)throw Error('Selecione estudantes.');if(!course.free&&!val('valid-until'))throw Error('Informe validade do acesso pago.');for(const uid of ids){const p=candidates.find(p=>p.id===uid);if(p.status==='pending')await D.patch('sparkProfiles/'+uid,{status:'active'});else if(p.status!=='active')throw Error(p.name+' está suspenso. Solicite liberação administrativa.');await D.put(cp()+'/students/'+uid,{uid,name:p.name,email:p.email,active:true,validUntil:D.Timestamp.fromDate(new Date((val('valid-until')||course.end)+'T23:59:59-03:00')),receiptLink:requests.find(r=>r.id===uid)?.receiptLink||'',approvedBy:user.uid,approvedAt:now()});await D.patch(cp(),{viewerUids:D.arrayUnion(uid)});if(requests.some(r=>r.id===uid))await D.remove(cp()+'/requests/'+uid);}roster();});on('roster-preview',async()=>{const f=$('roster-file').files[0];if(!f||f.size>5000000)throw Error('Escolha um JSON de até 5 MB.');const parsed=parseClassroomRoster(JSON.parse(await f.text()));const a=Array.isArray(parsed)?parsed:parsed.rows||parsed.students||[];let found=0;for(const p of candidates){const yes=a.some(r=>String(r.email||r.emailAddress||'').toLowerCase()===p.email.toLowerCase());if(yes){document.querySelector(`[data-enroll="${p.id}"]`).checked=true;found++;}}$('roster-preview-out').textContent=`${found} cadastros correspondentes selecionados. Confira e clique em Aprovar matrículas.`;});}
async function teamPanel(){const members=await D.list(cp()+'/team');page('Equipe de acompanhamento',`<p>A equipe pode ler o acompanhamento de todo este curso. As permissões abaixo controlam seus lançamentos. Use cursos separados para restringir disciplinas.</p>${field('team-uid','UID da pessoa aprovada pela administração')}${field('team-name','Nome / função')}<label><input id="observe" type="checkbox" checked> Observações</label><label><input id="council" type="checkbox"> Conselho de classe</label><label><input id="warnings" type="checkbox"> Advertências</label>${button('add-team','Salvar membro')}${table(['Nome / função','UID','Permissões','Ação'],members.map(m=>[esc(m.name),esc(m.uid),esc(m.permissions.join(', ')),button('rm-'+m.id,'Revogar','danger')]))}`);on('add-team',async()=>{const uid=val('team-uid');await D.put(cp()+'/team/'+uid,{uid,name:val('team-name'),permissions:['observe','council','warnings'].filter(k=>$(k).checked)});await D.patch(cp(),{viewerUids:D.arrayUnion(uid)});teamPanel();});for(const m of members)on('rm-'+m.id,async()=>{await D.remove(cp()+'/team/'+m.id);const remaining=(course.viewerUids||[]).filter(u=>u!==m.id);await D.patch(cp(),{viewerUids:remaining});course.viewerUids=remaining;teamPanel();});}
async function lessons(){const items=await D.list(cp()+'/lessons'),progress=await D.read(cp()+'/progress/'+user.uid).catch(()=>null),completed=progress?.completed||[];page('Conteúdos do curso',`${owner()?button('add-lesson','Adicionar conteúdo'):''}<p>${completed.length} conteúdos marcados como concluídos.</p>${items.map(l=>`<article class="card"><h2>${esc(l.title)}</h2><p>${esc(l.subject)}</p><div class="pre">${esc(l.body)}</div><p>${link(l.url,'Abrir material')}</p>${!owner()?button('done-'+l.id,completed.includes(l.id)?'Concluído':'Marcar como concluído'):''}</article>`).join('')}`);on('add-lesson',()=>{page('Adicionar conteúdo',`${field('lesson-title','Título')}${field('lesson-subject','Disciplina')}${area('lesson-body','Texto')}${field('lesson-url','Link HTTPS do material')}${button('lesson-save','Salvar')}`);on('lesson-save',async()=>{safeLink(val('lesson-url'));await D.put(cp()+'/lessons/'+id(),{title:val('lesson-title'),subject:val('lesson-subject'),body:val('lesson-body'),url:val('lesson-url')});lessons();});});for(const l of items)on('done-'+l.id,async()=>{await D.put(cp()+'/progress/'+user.uid,{completed:[...new Set([...completed,l.id])],updatedAt:now()});lessons();});}
async function exams(){const list=await D.list(cp()+'/exams',owner()?[]:[['published','==',true]]);page('Avaliações e quizzes',`${owner()&&!course.closed?button('new-exam','Cadastrar avaliação'):''}${list.map(e=>`<article class="card"><h2>${esc(e.title)}</h2><p>${esc(e.subject)} · ${esc(e.date)} · ${e.open?'Aberta':'Fechada'} · ${e.grading==='concept'?'Conceito':'Nota'}</p><p>${link(shareUrl(courseId,e.id),'Link da avaliação')} · ${link(shareUrl(courseId,e.id,true),'Link do quiz')}</p><div class="actions">${button('e-'+e.id,owner()?'Respostas e correção':'Responder')}${button('live-'+e.id,'Quiz ao vivo','outline')}${owner()?button('edit-'+e.id,'Editar','outline'):''}${owner()?button('toggle-'+e.id,e.open?'Fechar':'Liberar','outline'):''}</div></article>`).join('')}`);on('new-exam',()=>examEditor());for(const e of list){on('e-'+e.id,()=>{examId=e.id;return owner()?reviewList(e):takeExam(e);});on('edit-'+e.id,()=>examEditor(e));on('toggle-'+e.id,async()=>{await D.patch(cp()+'/exams/'+e.id,{open:!e.open,published:true});exams();});on('live-'+e.id,()=>{examId=e.id;return live(e);});}}
async function examEditor(existing){const key=existing?await D.read(`${cp()}/exams/${existing.id}/private/key`):null;const e=existing?{...existing,questions:existing.questions.map(q=>key.keys[q.id])}:structuredClone(SAMPLE);page('Cadastro de avaliação',`<p>Edite o JSON abaixo. Tipos: choice (uma correta), multiple (várias corretas), blanks (lacunas {{1}}), open (texto ou código). As alternativas são numeradas a partir de zero no gabarito. Em multiple, omissões e marcações erradas descontam uma fração do peso; mínimo zero.</p><p>Para apresentar código no enunciado, use <code>code</code> e <code>language</code>. Para resposta em código, use <code>responseFormat: "code"</code> em questão aberta.</p>${area('exam-json','Configuração e questões',JSON.stringify(e,null,2))}${button('exam-save','Salvar avaliação fechada')}`);on('exam-save',async()=>{const data=JSON.parse(val('exam-json'));const split=splitExam(data);const eid=existing?.id||id();const start=data.date?new Date(data.date+'T00:00:00-03:00'):new Date('2020-01-01');const end=data.date?new Date(data.date+'T23:59:59-03:00'):new Date('2100-01-01');const publicData={title:data.title,subject:data.subject||'',date:data.date||'',grading:data.grading,scale:data.scale,questions:split.questions,published:true,open:false,startAt:D.Timestamp.fromDate(start),endAt:D.Timestamp.fromDate(end)};if(existing){const submitted=await D.list(`${cp()}/exams/${eid}/attempts`);if(submitted.length)throw Error('Esta avaliação já tem entregas. Crie outra para alterar questões e pesos.');}await D.batch([{path:`${cp()}/exams/${eid}`,data:publicData},{path:`${cp()}/exams/${eid}/private/key`,data:{keys:split.keys}}]);exams();});}
function question(q){let prompt=esc(q.prompt);if(q.type==='blanks')prompt=prompt.replace(/\{\{(\d+)\}\}/g,(_,n)=>`<input aria-label="Lacuna ${n}" style="display:inline-block;width:180px" maxlength="100">`);return `<section class="card" id="q-${q.id}"><h2>${prompt}</h2>${q.code?`<pre style="background:#101418;color:#e8edf2;padding:20px;overflow:auto"><code>${esc(q.code)}</code></pre>`:''}${['choice','multiple'].includes(q.type)?q.options.map((s,i)=>`<label class="option"><input type="${q.type==='choice'?'radio':'checkbox'}" name="${q.id}" value="${i}">${esc(s)}</label>`).join(''):q.type==='open'?`<textarea rows="5" maxlength="20000" aria-label="Resposta" style="${q.responseFormat==='code'?'background:#101418;color:#e8edf2;font-family:monospace':''}"></textarea>`:''}</section>`;}
async function takeExam(e){examId=e.id;const prev=await D.read(ep()+'/attempts/'+user.uid);if(prev){const grade=await D.read(ep()+'/grades/'+user.uid);page('Sua entrega',`<p>Enviada em ${date(prev.submittedAt)}.</p>${grade?`<h2>${e.grading==='concept'?esc(grade.concept):grade.grade+' / '+e.scale}</h2>${Object.entries(grade.feedback).map(([k,v])=>`<p><strong>${esc(k)}</strong>: ${v.points} pontos · ${esc(v.feedback)}</p>`).join('')}`:'<p>Aguardando correção do professor.</p>'}`);return;}page(e.title,`<p>${esc(e.subject)} · Respostas enviadas uma única vez.</p><div class="notice">Saídas de foco e ações de copiar/colar podem ser registradas para análise do professor. Não comprovam fraude. O navegador não bloqueia nem detecta capturas de tela de forma confiável.</div>${e.questions.map(question).join('')}${button('submit','Enviar respostas')}`);assessment=e;on('submit',async()=>{const answers={};for(const q of e.questions)answers[q.id]=publicAnswers(q,$('q-'+q.id));if(!confirm('Enviar definitivamente? Depois não será possível alterar.'))return;await D.put(ep()+'/attempts/'+user.uid,{uid:user.uid,name:profile.name,answers,submittedAt:now()});assessment=null;takeExam(e);});}
let lastEvent=0;async function logEvent(type){if(!assessment||!user||Date.now()-lastEvent<1500)return;lastEvent=Date.now();try{await D.put(ep()+'/events/'+id(),{uid:user.uid,type,createdAt:now()});}catch(e){console.warn('Evento não registrado',e.code);}}
document.addEventListener('visibilitychange',()=>{if(document.hidden)logEvent('hidden');});window.addEventListener('blur',()=>logEvent('blur'));for(const t of ['copy','paste','contextmenu'])document.addEventListener(t,()=>logEvent(t));
async function reviewList(e){const attempts=await D.list(ep()+'/attempts'),grades=await D.list(ep()+'/grades');page('Entregas · '+e.title,table(['Aluno','Entregue em','Resultado','Ação'],attempts.map(a=>{const g=grades.find(g=>g.id===a.uid);return [esc(a.name),date(a.submittedAt),g?e.grading==='concept'?g.concept:g.grade:'A corrigir',button('review-'+a.uid,'Corrigir')];})));for(const a of attempts)on('review-'+a.uid,()=>review(e,a));}
async function review(e,a){const key=await D.read(ep()+'/private/key'),events=await D.list(ep()+'/events',[['uid','==',a.uid]]),previous=await D.read(ep()+'/grades/'+a.uid);page('Correção · '+a.name,`${e.questions.map(q=>`<section class="card"><h2>${esc(q.prompt)}</h2><pre style="white-space:pre-wrap">${esc(JSON.stringify(a.answers[q.id],null,2))}</pre>${q.type==='open'?field('points-'+q.id,`Pontos (0 a ${q.points})`,previous?.feedback?.[q.id]?.points||0,'number'):'<p>Correção automática ao salvar no painel do professor.</p>'}${field('feedback-'+q.id,'Feedback',previous?.feedback?.[q.id]?.feedback||'')}</section>`).join('')}${select('grade-period','Período para lançar no conselho',course.periods.map(p=>[p,p]),course.periods[0])}${field('deduction','Desconto em pontos brutos (após análise do professor)',0,'number')}${field('reason','Justificativa do desconto')}${button('grade-save','Calcular e publicar resultado')}<h2>Registros de navegação</h2><p>Eventos são indícios técnicos, não prova de fraude. Não há detecção garantida de prints.</p>${table(['Evento','Momento'],events.map(v=>[esc(v.type),date(v.createdAt)]))}`);on('grade-save',async()=>{const manual={};for(const q of e.questions)manual[q.id]={points:Number($('points-'+q.id)?.value||0),feedback:val('feedback-'+q.id)};const g=gradeAttempt(e,key.keys,a.answers,manual),discount=Number(val('deduction'));if(!Number.isFinite(discount)||discount<0||discount>g.total||(discount>0&&!val('reason')))throw Error('Desconto inválido ou sem justificativa.');g.earned=Math.max(0,g.earned-discount);g.percent=g.earned/g.total*100;g.grade=Math.round(g.percent/100*e.scale*100)/100;g.concept=g.percent>=99.999?'A':g.percent>=70?'B':g.percent>=40?'C':'D';await D.put(ep()+'/grades/'+a.uid,{...g,grading:e.grading,scale:e.scale,discount,reason:val('reason'),authorUid:user.uid,authorName:profile.name,updatedAt:now()});await D.put(cp()+'/records/'+id(),{kind:'result',studentUid:a.uid,studentName:a.name,subject:e.subject,period:val('grade-period'),grading:e.grading,concept:g.concept,grade:g.grade,scale:e.scale,text:'Avaliação: '+e.title,authorUid:user.uid,authorName:profile.name,createdAt:now()}).catch(err=>{console.warn('Lançamento no acompanhamento indisponível',err.code);});reviewList(e);});}
async function live(e){examId=e.id;const state=await D.read(ep()+'/live/state');if(!owner()){page('Quiz ao vivo · '+e.title,'<div id="live-student">Aguardando professor…</div>');const render=s=>{if(!s||!s.open){$('live-student').innerHTML='<p>Aguarde a abertura da pergunta.</p>';return;}const q=e.questions.find(q=>q.id===s.questionId);if(!q)return;const sent=localStorage.getItem(`spark-live-${courseId}-${examId}-${user.uid}-${q.id}`);$('live-student').innerHTML=sent?'<p>Resposta enviada. Aguarde a próxima pergunta.</p>':question(q)+button('live-send','Enviar');on('live-send',async()=>{const answer=publicAnswers(q,$('q-'+q.id));await D.put(ep()+'/liveAnswers/'+user.uid+'_'+q.id,{uid:user.uid,name:profile.name,questionId:q.id,answer,createdAt:now()});localStorage.setItem(`spark-live-${courseId}-${examId}-${user.uid}-${q.id}`,'1');render(s);});};unsubs.push(D.watch(ep()+'/live/state',render,error));return;}
page('Quiz ao vivo · '+e.title,`${select('live-question','Pergunta',e.questions.filter(q=>q.type!=='blanks').map(q=>[q.id,q.prompt]),state?.questionId)}${select('chart','Gráfico',[['bars','Barras'],['pie','Pizza'],['dots','Bolinhas'],['wordcloud','Nuvem de palavras']],'bars')}${select('values','Valores',[['count','Numérico'],['percent','Porcentagem']],'count')}<div class="actions">${button('live-open','Abrir pergunta')}${button('live-close','Encerrar respostas','outline')}</div><p id="live-state"></p><div id="live-chart" class="card"></div>`);let responses=[];const render=()=>{const q=e.questions.find(q=>q.id===val('live-question')),rows=responses.filter(r=>r.questionId===q.id);$('live-chart').innerHTML=chart(q,rows,val('chart'),val('values'));};on('live-open',async()=>{await D.patch(ep(),{open:true,published:true});await D.put(ep()+'/live/state',{open:true,questionId:val('live-question')});$('live-state').textContent='Recebendo respostas. Cada estudante pode responder uma vez por pergunta.';});on('live-close',async()=>{await D.put(ep()+'/live/state',{open:false,questionId:val('live-question')});$('live-state').textContent='Respostas encerradas.';});for(const k of ['live-question','chart','values'])$(k).onchange=render;unsubs.push(D.watchList(ep()+'/liveAnswers',[],r=>{responses=r;render();},error));}
function chart(q,rows,type,values){const counts=new Map();if(q.options)q.options.forEach((v,i)=>counts.set(String(i),0));for(const r of rows){if(q.type==='multiple'&&Array.isArray(r.answer))for(const n of new Set(r.answer))if(counts.has(String(n)))counts.set(String(n),counts.get(String(n))+1);else{}else if(q.type==='choice'){if(counts.has(String(r.answer)))counts.set(String(r.answer),counts.get(String(r.answer))+1);}else if(typeof r.answer==='string'){const words=type==='wordcloud'?[...new Set(r.answer.toLocaleLowerCase('pt-BR').match(/[\p{L}\p{N}]+/gu)||[])]:[r.answer];for(const w of words)counts.set(w,(counts.get(w)||0)+1);}}const total=[...counts.values()].reduce((a,b)=>a+b,0),max=Math.max(1,...counts.values()),colors=['#176f60','#c76740','#4479af','#9064b1','#b29430','#3b8892'];const entries=[...counts].slice(0,100);const label=n=>values==='percent'?`${(n/Math.max(1,type==='pie'?total:rows.length)*100).toFixed(1)}%`:n;let visual='';if(type==='wordcloud')visual=entries.map(([k,n],i)=>`<span style="display:inline-block;margin:10px;color:${colors[i%6]};font-size:${16+32*n/max}px">${esc(q.options?q.options[Number(k)]:k)} (${label(n)})</span>`).join('');else if(type==='pie'){let angle=0;const stops=entries.filter(([,n])=>n>0).map(([,n],i)=>{const start=angle;angle+=n/Math.max(1,total)*360;return `${colors[i%6]} ${start}deg ${angle}deg`;});visual=`<div role="img" aria-label="Gráfico de pizza; dados na tabela abaixo" style="width:220px;height:220px;border-radius:50%;background:${stops.length?'conic-gradient('+stops.join(',')+')':'#ddd'}"></div>`;}else visual=entries.map(([k,n])=>`<p>${esc(q.options?q.options[Number(k)]:k)}: <strong>${label(n)}</strong></p>${type==='dots'?`<div aria-label="${n} respostas" style="color:#176f60;font-size:22px">${'● '.repeat(Math.min(n,60))}${n>60?' +'+(n-60):''}</div>`:`<div style="height:20px;background:#176f60;width:${n/max*100}%"></div>`}`).join('');return `<h2>${rows.length} respostas</h2><p>${q.type==='multiple'?'Múltiplas escolhas: barras/bolinhas usam respondentes; pizza usa marcações.':''}</p>${visual}${table(['Resposta','Contagem','Exibição'],entries.map(([k,n])=>[esc(q.options?q.options[Number(k)]:k),n,label(n)]))}`;}
async function tracking(){const students=await D.list(cp()+'/students'),records=await D.list(cp()+'/records');page('Acompanhamento geral',`<p>Vermelho: dois conceitos D ou uma nota inferior a 70% da escala. Resultados anteriores continuam visíveis nos períodos seguintes.</p>${table(['Aluno','Situação','Ação'],students.map(s=>{const results=latestResults(records.filter(r=>r.studentUid===s.uid&&r.kind==='result'));return [esc(s.name),risk(results)?'<strong style="color:#b42318">Acompanhamento prioritário</strong>':'Regular',button('student-'+s.uid,'Abrir histórico')];}))}`);for(const s of students)on('student-'+s.uid,()=>dossier(s));}
function latestResults(rows){const map=new Map();for(const r of rows.sort((a,b)=>(a.createdAt?.seconds||0)-(b.createdAt?.seconds||0)))map.set(r.subject+'|'+r.period,r);return [...map.values()];}
async function dossier(s){const records=await D.list(cp()+'/records',[['studentUid','==',s.uid]]);page('Histórico · '+s.name,`${table(['Data','Tipo / disciplina / período','Autor','Resultado / observação','Documento'],records.sort((a,b)=>(b.createdAt?.seconds||0)-(a.createdAt?.seconds||0)).map(r=>[date(r.createdAt),esc([r.kind,r.subject,r.period].filter(Boolean).join(' / ')),esc(r.authorName),esc(r.kind==='result'?(r.grading==='concept'?r.concept:r.grade+' / '+r.scale)+' · '+r.text:r.text),r.kind==='written'?button('print-'+r.id,'Imprimir'):link(r.documentLink)]))}<h2>Novo lançamento</h2>${select('record-kind','Tipo',[['observation','Observação'],['result','Nota/conceito para conselho'],['verbal','Advertência verbal'],['written','Advertência escrita']],'observation')}${select('record-subject','Disciplina',(course.subjects||[]).map(s=>[s,s]),course.subjects?.[0])}${select('record-period','Período',course.periods.map(s=>[s,s]),course.periods[0])}${select('record-grading','Avaliação',[['concept','Conceito'],['grade','Nota']],'concept')}${select('record-concept','Conceito',['A','B','C','D'].map(s=>[s,s]),'A')}${field('record-grade','Nota',0,'number')}${field('record-scale','Nota máxima',100,'number')}${area('record-text','Observação / motivo da advertência')}${field('record-document','Documento adicional: link HTTPS')}${button('record-save','Registrar')}`);for(const r of records)on('print-'+r.id,()=>printWarning(s,r));on('record-save',async()=>{const kind=val('record-kind'),grade=Number(val('record-grade')),scale=Number(val('record-scale'));if(kind==='result'&&(!Number.isFinite(grade)||!Number.isFinite(scale)||scale<=0||grade<0||grade>scale))throw Error('Nota/escala inválida.');safeLink(val('record-document'));const r={kind,studentUid:s.uid,studentName:s.name,subject:val('record-subject'),period:val('record-period'),grading:val('record-grading'),concept:val('record-concept'),grade,scale,text:val('record-text'),documentLink:val('record-document'),authorUid:user.uid,authorName:profile.name,createdAt:now(),header:course.warningHeader||'',footer:course.warningFooter||'',letterhead:course.letterhead||''};if(!r.text&&kind!=='result')throw Error('Descreva a observação/ocorrência.');await D.put(cp()+'/records/'+id(),r);dossier(s);});}
function printWarning(s,r){const w=window.open('','_blank');if(!w)throw Error('Permita a abertura da janela de impressão.');w.opener=null;w.document.write(`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Advertência</title><style>body{font:16px Arial;margin:22mm;line-height:1.6}footer{margin-top:50px}a{word-break:break-all}</style></head><body><header>${esc(r.header)}</header><h1>Advertência por escrito</h1><p>Curso: ${esc(course.title)} · Turma: ${esc(course.group)}</p><p>Estudante: ${esc(s.name)}</p><p>Data: ${esc(date(r.createdAt))}</p><p style="white-space:pre-wrap">${esc(r.text)}</p><p>Responsável pelo registro: ${esc(r.authorName)}</p><p>${link(r.letterhead,'Modelo/papel timbrado externo')}</p><p>____________________________<br>Ciência do estudante / responsável</p><footer>${esc(r.footer)}</footer></body></html>`);w.document.close();w.print();}
async function report(){const students=await D.list(cp()+'/students'),all=await D.list(cp()+'/records'),rows=[];for(const s of students)for(const subject of course.subjects){const results=latestResults(all.filter(r=>r.studentUid===s.uid&&r.subject===subject&&r.kind==='result'));rows.push([esc(s.name),esc(subject),...course.periods.map(p=>{const r=results.find(r=>r.period===p);return r?esc(r.grading==='concept'?r.concept:r.grade+' / '+r.scale):'—';})]);}const html=`<h1>${esc(course.title)} · Conselho acumulativo</h1><p>Períodos apresentados lado a lado, sem somar conceitos. Autor e revisões ficam no histórico do aluno.</p>${table(['Estudante','Disciplina',...course.periods.map(esc)],rows)}`;page('Relatório de conselho',html+button('report-print','Imprimir / salvar PDF')+button('report-download','Baixar relatório HTML','outline'));on('report-print',()=>window.print());on('report-download',()=>download('conselho-'+courseId+'.html','<!doctype html><meta charset="utf-8">'+html,'text/html'));return html;}
async function bankPanel(){const items=await D.list('sparkBank',[['ownerUid','==',user.uid]]);page('Banco de questões',`<p>Questões particulares do professor. Copie a questão para o JSON de uma avaliação.</p>${area('bank-json','Questão em JSON',JSON.stringify(SAMPLE.questions[0],null,2))}${button('bank-save','Salvar questão')}<div>${items.map(q=>`<details><summary>${esc(q.question.prompt)}</summary><pre>${esc(JSON.stringify(q.question,null,2))}</pre></details>`).join('')}</div>`);on('bank-save',async()=>{const question=JSON.parse(val('bank-json'));splitExam({...SAMPLE,questions:[question]});await D.put('sparkBank/'+id(),{ownerUid:user.uid,question});bankPanel();});}
const childCollections=['team','requests','students','lessons','progress','records','exams','closures'];
async function collectCourse(cid){const prefix='sparkCourses/'+cid,c=await D.read(prefix),out=[{path:prefix,data:D.encode(stripId(c))}];for(const col of childCollections){const rows=await D.list(prefix+'/'+col);for(const row of rows){const path=prefix+'/'+col+'/'+row.id;out.push({path,data:D.encode(stripId(row))});if(col==='exams')for(const sub of ['private','attempts','grades','events','live','liveAnswers'])for(const child of await D.list(path+'/'+sub))out.push({path:path+'/'+sub+'/'+child.id,data:D.encode(stripId(child))});}}return out;}
function stripId({id,...data}){return data;}
async function backupPanel(){page('Backup e restauração',`<p>Backup JSON desta edição Spark: perfis, planos, cursos, matrículas, conteúdos, avaliações, gabaritos, respostas, acompanhamento e demonstração. Não inclui contas do Authentication, documentos externos ou o cadastro de administradores.</p>${button('backup-export','Baixar backup completo')}<h2>Restaurar</h2><p>Restauração administrativa, em lotes. Sobrescreve caminhos presentes no JSON, preserva os demais e pode ficar parcial se houver falha. Guarde um backup atual antes de prosseguir.</p><input id="backup-file" type="file" accept="application/json">${field('restore-confirm','Digite RESTAURAR')}${button('backup-restore','Restaurar backup','danger')}<p id="backup-status"></p>`);on('backup-export',async()=>{const docs=[];for(const root of ['sparkProfiles','sparkPlans','sparkPlanPayments','sparkInvites','sparkLeads','sparkBank'])for(const row of await D.list(root))docs.push({path:root+'/'+row.id,data:D.encode(stripId(row))});for(const c of await D.list('sparkCourses'))docs.push(...await collectCourse(c.id));download('conexoes-backup-'+new Date().toISOString().slice(0,10)+'.json',{format:'conexoes-spark-1',createdAt:new Date().toISOString(),docs});$('backup-status').textContent='Download solicitado. Confira se o arquivo foi salvo no computador.';});on('backup-restore',async()=>{if(val('restore-confirm')!=='RESTAURAR')throw Error('Confirme digitando RESTAURAR.');const f=$('backup-file').files[0];if(!f||f.size>20000000)throw Error('Selecione um JSON de até 20 MB.');const b=validateBackup(JSON.parse(await f.text()));if(!confirm(`Restaurar ${b.docs.length} documentos?`))return;await D.batch(b.docs.map(x=>({path:x.path,data:D.decode(x.data)})));$('backup-status').textContent='Restauração concluída.';});}
async function closure(){if(course.closed){return closedCourse();}
page('Fechamento do curso / ano',`<p>O relatório apresenta todos os períodos do curso e suas disciplinas. Feche cada curso do ano desejado separadamente.</p><p>Antes de encerrar, visualize os relatórios e confira o download do backup JSON.</p>${button('close-report','1. Visualizar e baixar relatório')}${button('close-backup','2. Baixar backup do curso')}<div id="close-output"></div><label><input id="close-read" type="checkbox"> Visualizei o relatório de fechamento.</label><label><input id="close-downloaded" type="checkbox"> Confirmei que o backup JSON foi salvo e pode ser recuperado.</label>${button('close-final','3. Encerrar e bloquear lançamentos','danger')}`);let viewed=false,downloaded=false,downloadHash='';on('close-report',async()=>{const students=await D.list(cp()+'/students'),records=await D.list(cp()+'/records');const html=`<h1>Fechamento · ${esc(course.title)}</h1><p>${esc(course.start)} a ${esc(course.end)}</p>${table(['Aluno','Disciplina','Período','Resultado','Autor','Observação'],records.map(r=>[esc(students.find(s=>s.uid===r.studentUid)?.name||r.studentName),esc(r.subject),esc(r.period),r.kind==='result'?esc(r.grading==='concept'?r.concept:r.grade+' / '+r.scale):esc(r.kind),esc(r.authorName),esc(r.text)]))}`;$('close-output').innerHTML=html;download('fechamento-'+courseId+'.html','<!doctype html><meta charset="utf-8">'+html,'text/html');viewed=true;});on('close-backup',async()=>{const docs=await collectCourse(courseId);download('curso-'+courseId+'.json',{format:'conexoes-spark-1',createdAt:new Date().toISOString(),docs});downloadHash=await fingerprint(docs);downloaded=true;});on('close-final',async()=>{if(!viewed||!downloaded||!$('close-read').checked||!$('close-downloaded').checked)throw Error('Conclua o relatório, o download e as confirmações.');if(await fingerprint(await collectCourse(courseId))!==downloadHash)throw Error('Dados mudaram após o backup. Gere novamente o relatório e o backup antes de encerrar.');await D.put(cp()+'/closures/'+id(),{authorUid:user.uid,authorName:profile.name,createdAt:now(),reportConfirmed:true,backupConfirmed:true,snapshotHash:downloadHash});await D.patch(cp(),{closed:true});openCourse(courseId);});}
async function renewPlan(){const plans=await D.list('sparkPlans');page('Meu plano e renovação',`<p>Plano atual: ${esc(profile.planId||'free')} · Validade: ${esc(date(profile.planExpiresAt))}</p><p>Realize o pagamento fora da aplicação e informe um link de comprovante que a administração consiga abrir.</p>${select('renew-plan','Plano',plans.length?plans.map(p=>[p.id,p.title]):[['free','Free']],profile.planId||'free')}${select('renew-cycle','Ciclo',[['monthly','Mensal'],['quarterly','Trimestral'],['semiannual','Semestral'],['yearly','Anual']],'monthly')}${field('renew-proof','Link HTTPS do comprovante')}${button('renew-send','Solicitar validação')}`);on('renew-send',async()=>{if(!val('renew-proof'))throw Error('Informe o comprovante.');safeLink(val('renew-proof'));await D.put('sparkPlanPayments/'+user.uid,{uid:user.uid,planId:val('renew-plan'),cycle:val('renew-cycle'),receiptLink:val('renew-proof'),createdAt:now()});alert('Solicitação enviada. A administração validará o comprovante e a data de vencimento.');home();});}
async function fingerprint(docs){const ordered=v=>Array.isArray(v)?v.map(ordered):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,ordered(v[k])])):v;const text=JSON.stringify(ordered([...docs].sort((a,b)=>a.path.localeCompare(b.path))));return [...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text)))].map(n=>n.toString(16).padStart(2,'0')).join('');}
async function closedCourse(){page('Curso encerrado',`<p>Curso bloqueado para novos lançamentos. As contas e outros cursos serão preservados.</p>${button('closed-report','Visualizar e baixar relatório')}${isAdmin?button('closed-backup','Baixar backup atualizado'):''}<div id="closed-report-out"></div>${isAdmin?`<label><input id="purge-report" type="checkbox"> Visualizei os relatórios de fechamento.</label><label><input id="purge-backup" type="checkbox"> Confirmei que o backup JSON foi salvo e poderá ser recuperado.</label>${field('purge-text','Digite EXCLUIR '+courseId)}${button('purge','Excluir dados deste curso','danger')}`:''}`);let seen=false,downloaded=false,hash='';on('closed-report',async()=>{const records=await D.list(cp()+'/records');const html=`<h1>${esc(course.title)} · Fechamento</h1>${table(['Aluno','Disciplina','Período','Resultado / registro','Autor'],records.map(r=>[esc(r.studentName),esc(r.subject),esc(r.period),esc(r.kind==='result'?(r.grading==='concept'?r.concept:r.grade+' / '+r.scale):r.text),esc(r.authorName)]))}`;$('closed-report-out').innerHTML=html;download('fechamento-'+courseId+'.html','<!doctype html><meta charset="utf-8">'+html,'text/html');seen=true;});on('closed-backup',async()=>{const docs=await collectCourse(courseId);download('curso-encerrado-'+courseId+'.json',{format:'conexoes-spark-1',createdAt:new Date().toISOString(),docs});hash=await fingerprint(docs);downloaded=true;});on('purge',async()=>{if(!seen||!downloaded||!$('purge-report').checked||!$('purge-backup').checked||val('purge-text')!=='EXCLUIR '+courseId)throw Error('Visualize o relatório, baixe o backup e preencha todas as confirmações.');const docs=await collectCourse(courseId);if(await fingerprint(docs)!==hash)throw Error('Dados mudaram após o backup. Baixe novamente antes de excluir.');if(!confirm('A exclusão dos dados deste curso será definitiva no banco. Continuar?'))return;await D.batch(docs.reverse().map(d=>({path:d.path,delete:true})));await D.remove('sparkInvites/'+courseId);home();});}
function shareUrl(cid,eid='',quiz=false){const u=new URL(location.href);u.search='';u.hash='';u.searchParams.set('curso',cid);if(eid)u.searchParams.set('avaliacao',eid);if(quiz)u.searchParams.set('quiz','1');return u.href;}
async function routeLink(){const u=new URL(location.href),cid=u.searchParams.get('curso'),eid=u.searchParams.get('avaliacao');if(!cid||!/^[\w-]+$/.test(cid))return;try{await openCourse(cid);}catch(e){if(e.code==='permission-denied'){joinCourse();$('join-code').value=cid;return;}throw e;}if(eid&&/^[\w-]+$/.test(eid)){examId=eid;const e=await D.read(ep());if(!e)throw Error('Avaliação não encontrada.');if(u.searchParams.get('quiz')==='1')await live(e);else await(owner()?reviewList(e):takeExam(e));}}
